INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (2, '60ff4f9e-71a1-4682-b67c-9d034f1dc24f', 1, '{"title": {"eng": "Writing Clear Website Content", "idn": "Menyusun Konten Website yang Mudah Dibaca"}, "content": [{"cta": null, "text": {"eng": "Start with the purpose of your page. Explain the information in simple language.\n\nReaders usually arrive with a specific question. Put the main answer first, then add explanations and examples in the following paragraphs. Keep each paragraph focused on one idea so changes of topic are easy to follow.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Mulai dari tujuan halaman. Tuliskan informasi yang ingin disampaikan dengan bahasa sederhana.\n\nPembaca biasanya datang dengan pertanyaan tertentu. Letakkan jawaban utama di awal, lalu tambahkan penjelasan dan contoh pada paragraf berikutnya. Satu paragraf sebaiknya membahas satu gagasan agar perubahan topik mudah diikuti.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/1f62608c-dd7c-465a-acd6-58f2b066027f.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Organize content into short sections and use images that support your message.\n\nRead the text again without looking at the page design. Mark sentences that need a second reading and replace unexplained terms. Then check whether the headline, summary, and article communicate a consistent message.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Susun konten dalam bagian yang singkat, lalu gunakan gambar yang membantu pembaca memahami pesan.\n\nBaca kembali tulisan tanpa melihat rancangan halaman. Tandai kalimat yang perlu dibaca dua kali dan ganti istilah yang belum dijelaskan. Setelah itu, periksa apakah judul, ringkasan, dan isi artikel menyampaikan pesan yang konsisten.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": "https://cdn.dicobainaja.com/uploads/1b55246a-36b6-4069-9069-eed1103abd73.png"}], "excerpt": {"eng": "A sample article to try the jorTemplate blog.", "idn": "Artikel contoh untuk mencoba fitur blog jorTemplate."}}', 'https://cdn.dicobainaja.com/uploads/1b55246a-36b6-4069-9069-eed1103abd73.png', 'menyusun-konten-website-1791357716', 'active', '2026-10-07 14:21:56.49+07', NULL, '2026-10-07 15:17:39.024+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (4, 'bbf9eebf-dfe8-45e5-8eeb-930f8fc2c3ea', 1, '{"title": {"eng": "Writing Clear Website Content", "idn": "Menyusun Konten Website yang Mudah Dibaca"}, "content": [{"cta": null, "text": {"eng": "Start with the purpose of your page. Explain the information in simple language.", "idn": "Mulai dari tujuan halaman. Tuliskan informasi yang ingin disampaikan dengan bahasa sederhana."}, "image": "https://cdn.dicobainaja.com/uploads/1f62608c-dd7c-465a-acd6-58f2b066027f.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Organize content into short sections and use images that support your message.", "idn": "Susun konten dalam bagian yang singkat, lalu gunakan gambar yang membantu pembaca memahami pesan."}, "image": "https://cdn.dicobainaja.com/uploads/1b55246a-36b6-4069-9069-eed1103abd73.png"}], "excerpt": {"eng": "A sample article to try the jorTemplate blog.", "idn": "Artikel contoh untuk mencoba fitur blog jorTemplate."}}', 'https://cdn.dicobainaja.com/uploads/1b55246a-36b6-4069-9069-eed1103abd73.png', 'hapus-test-1791357716', 'inactive', '2026-10-07 14:21:56.539+07', '2026-10-07 14:21:56.541+07', '2026-10-07 14:21:56.541+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (1, '1693ad4b-e1c6-4b99-add7-27c7237f417a', 1, '{"title": {"eng": "Getting Started with jorTemplate: A Quick Guide", "idn": "Memulai Website dengan jorTemplate: Panduan Singkat"}, "content": [{"cta": null, "text": {"eng": "Start with the purpose of your page. Explain the information in simple language.\n\nBefore choosing colors and images, describe your visitors’ needs in one sentence. A small business website might need to explain its products, ordering process, and support channels. Start with pages that serve those needs to keep the project focused.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Mulai dari tujuan halaman. Tuliskan informasi yang ingin disampaikan dengan bahasa sederhana.\n\nSebelum memilih warna dan gambar, tuliskan kebutuhan pengunjung dalam satu kalimat. Website usaha kecil, misalnya, perlu menjelaskan produk, cara memesan, dan saluran bantuan. Mulailah dari halaman yang mendukung kebutuhan tersebut agar proses pengerjaan tetap terarah.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/1f62608c-dd7c-465a-acd6-58f2b066027f.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Organize content into short sections and use images that support your message.\n\nPrepare real sample content before arranging the layout. Long titles, portrait images, and contact details often reveal problems that short placeholder text hides. Try the full journey from opening the home page to finding the information you need.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Susun konten dalam bagian yang singkat, lalu gunakan gambar yang membantu pembaca memahami pesan.\n\nSiapkan contoh konten nyata sebelum mengatur layout. Judul panjang, foto vertikal, dan nomor kontak sering menunjukkan masalah yang tidak terlihat ketika memakai teks singkat. Coba seluruh alur dari membuka halaman utama sampai menemukan informasi yang dicari.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": "https://cdn.dicobainaja.com/uploads/1b55246a-36b6-4069-9069-eed1103abd73.png"}], "excerpt": {"eng": "A sample article to try the jorTemplate blog.", "idn": "Artikel contoh untuk mencoba fitur blog jorTemplate."}}', 'https://cdn.dicobainaja.com/uploads/1f62608c-dd7c-465a-acd6-58f2b066027f.png', 'memulai-website-jortemplate-1791357716', 'active', '2026-10-07 14:21:56.465+07', NULL, '2026-10-07 15:17:39.02+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (5, '2c1d97ed-4f12-4f6d-b799-45e8a5bf5a42', 1, '{"title": {"eng": "Define Your Website Goals Before Starting", "idn": "Menentukan Tujuan Website Sebelum Mulai"}, "content": [{"cta": null, "text": {"eng": "Identify your primary readers and the action you want them to take. A clear goal helps you choose the content they actually need.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nSeparate visitor goals from team goals. Visitors may want to compare options while the team wants relevant inquiries. Clear product information and an easy-to-find contact path can serve both needs.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Tentukan siapa pembaca utama dan tindakan yang ingin mereka lakukan. Tujuan yang jelas membantu memilih konten yang benar-benar diperlukan.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nBedakan tujuan pengunjung dan tujuan tim. Pengunjung mungkin ingin membandingkan pilihan, sementara tim ingin menerima pertanyaan yang relevan. Kedua kebutuhan dapat bertemu melalui penjelasan produk yang jelas dan jalur kontak yang mudah ditemukan.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/1f62608c-dd7c-465a-acd6-58f2b066027f.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nChoose one primary action for each page. Note the information a person needs before they are ready to take it. Use those notes to decide the content order instead of following a layout simply because it looks attractive.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nPilih satu tindakan utama untuk setiap halaman. Catat informasi yang dibutuhkan sebelum seseorang siap melakukan tindakan itu. Gunakan catatan tersebut untuk menentukan urutan konten, bukan sekadar mengikuti layout yang terlihat menarik.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Identify your primary readers and the action you want them to take. A clear goal helps you choose the content they actually need.", "idn": "Tentukan siapa pembaca utama dan tindakan yang ingin mereka lakukan. Tujuan yang jelas membantu memilih konten yang benar-benar diperlukan."}}', 'https://cdn.dicobainaja.com/uploads/1f62608c-dd7c-465a-acd6-58f2b066027f.png', 'menentukan-tujuan-website-sebelum-mulai-1791359671', 'active', '2026-10-07 14:54:31.355+07', NULL, '2026-10-07 15:17:39.025+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (6, 'da0cf000-03a4-4880-afb1-558f6faac4bb', 1, '{"title": {"eng": "Create Navigation That Is Easy to Understand", "idn": "Membuat Navigasi yang Mudah Dipahami"}, "content": [{"cta": null, "text": {"eng": "Use familiar menu labels. Put important pages in the main navigation so visitors can find them easily.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nMenu labels should explain the destination before a click. Labels such as Products, Blog, and Contact are easy to recognize when their pages match expectations. Avoid presenting too many equally prominent choices on a single row.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Gunakan nama menu yang familiar. Tempatkan halaman penting pada navigasi utama agar pengunjung mudah menemukannya.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nNama menu perlu menjelaskan tujuan halaman sebelum diklik. Istilah seperti Produk, Blog, dan Kontak lebih mudah dikenali ketika isinya sesuai harapan. Hindari menempatkan terlalu banyak pilihan dengan tingkat kepentingan yang sama pada satu baris.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/1b55246a-36b6-4069-9069-eed1103abd73.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nTest navigation from a detail page, not just the home page. Readers should be able to return to the article list without losing their bearings. On mobile, make sure the menu stays clear and links can be tapped without hitting adjacent choices.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nUji navigasi dari halaman detail, bukan hanya halaman utama. Pembaca perlu bisa kembali ke daftar artikel tanpa kehilangan arah. Pada ponsel, pastikan menu tetap terlihat jelas dan setiap tautan dapat disentuh tanpa mengenai pilihan di sebelahnya.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Use familiar menu labels. Put important pages in the main navigation so visitors can find them easily.", "idn": "Gunakan nama menu yang familiar. Tempatkan halaman penting pada navigasi utama agar pengunjung mudah menemukannya."}}', 'https://cdn.dicobainaja.com/uploads/1b55246a-36b6-4069-9069-eed1103abd73.png', 'membuat-navigasi-yang-mudah-dipahami-1791359671', 'active', '2026-10-07 14:54:31.363+07', NULL, '2026-10-07 15:17:39.025+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (8, '093814c9-b12b-4f82-a0d3-9605492dd1c8', 1, '{"title": {"eng": "Choose Images for Product Pages", "idn": "Memilih Gambar untuk Halaman Produk"}, "content": [{"cta": null, "text": {"eng": "Choose images that show product shape and details. Keep lighting consistent so visitors can compare their options.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nUse angles that help readers understand the product. An overall view can be paired with detail images showing materials or important features. A quiet background keeps attention on the object you are explaining.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Pilih gambar yang menunjukkan bentuk dan detail produk. Gunakan pencahayaan yang konsisten agar pengunjung mudah membandingkan pilihan.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nGunakan sudut pengambilan yang membantu pembaca memahami produk. Foto keseluruhan dapat dilengkapi gambar detail untuk menunjukkan bahan atau bagian penting. Latar yang tenang membuat perhatian tetap tertuju pada objek yang ingin dijelaskan.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/6a2ddb0f-7c0e-414d-bb03-841f0648cfc5.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nCheck how images are cropped in lists and detail pages. Important product features should remain visible on small screens. Keep the originals and use recognizable filenames to make later image updates easier.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nPeriksa hasil pemotongan gambar pada daftar dan halaman detail. Bagian penting produk harus tetap terlihat pada layar kecil. Simpan versi asli dan beri nama file yang mudah dikenali agar pembaruan gambar berikutnya tidak membingungkan.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Choose images that show product shape and details. Keep lighting consistent so visitors can compare their options.", "idn": "Pilih gambar yang menunjukkan bentuk dan detail produk. Gunakan pencahayaan yang konsisten agar pengunjung mudah membandingkan pilihan."}}', 'https://cdn.dicobainaja.com/uploads/6a2ddb0f-7c0e-414d-bb03-841f0648cfc5.png', 'memilih-gambar-untuk-halaman-produk-1791359671', 'active', '2026-10-07 14:54:31.376+07', NULL, '2026-10-07 15:17:39.027+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (10, 'e5fda450-f592-45eb-8072-16e329f12d46', 1, '{"title": {"eng": "Build a Short Contact Form", "idn": "Membuat Formulir Kontak yang Ringkas"}, "content": [{"cta": null, "text": {"eng": "Ask for the information you need to reply. Use clear labels and show a confirmation after the form is submitted.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nEvery field adds work for visitors. Decide why a name, email address, or phone number is needed before adding it to the form. Explain expected formats with short examples placed near the relevant fields.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Tanyakan informasi yang memang diperlukan untuk membalas pesan. Beri label yang jelas dan tampilkan konfirmasi setelah formulir terkirim.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nSetiap kolom menambah pekerjaan bagi pengunjung. Tentukan alasan mengapa nama, email, atau nomor telepon dibutuhkan sebelum memasukkannya ke formulir. Jelaskan format yang diharapkan melalui contoh pendek yang dekat dengan kolom terkait.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/41bb7e1f-44bc-4aca-88d0-d78b3c6e77df.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nTry submitting empty fields, invalid formats, and requests with an interrupted connection. Error messages should help people fix the issue without deleting their input. After success, show a clear confirmation so they do not submit again.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nCoba kirim formulir dengan data kosong, format salah, dan koneksi yang terputus. Pesan kegagalan perlu membantu orang memperbaiki masalah tanpa menghapus input mereka. Setelah berhasil, tampilkan konfirmasi yang jelas agar orang tidak mengirim ulang.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Ask for the information you need to reply. Use clear labels and show a confirmation after the form is submitted.", "idn": "Tanyakan informasi yang memang diperlukan untuk membalas pesan. Beri label yang jelas dan tampilkan konfirmasi setelah formulir terkirim."}}', 'https://cdn.dicobainaja.com/uploads/41bb7e1f-44bc-4aca-88d0-d78b3c6e77df.png', 'membuat-formulir-kontak-yang-ringkas-1791359671', 'active', '2026-10-07 14:54:31.385+07', NULL, '2026-10-07 15:17:39.029+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (7, '6d031abe-f00b-4527-9e4a-287f8d782b12', 1, '{"title": {"eng": "Write Clear Article Headlines", "idn": "Menulis Judul Artikel yang Jelas"}, "content": [{"cta": null, "text": {"eng": "A headline should explain what the reader will find. Use specific words and make sure the article delivers on its promise.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nA specific headline helps readers judge an article’s value. Name the problem or outcome the text actually covers without promising something it does not deliver. Put extra explanation in the summary to keep the headline easy to scan.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Judul perlu menjelaskan apa yang akan dibaca. Gunakan kata yang spesifik dan pastikan isi artikel memenuhi janji pada judul.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nJudul yang spesifik membantu pembaca menilai manfaat artikel. Sebutkan masalah atau hasil yang benar-benar dibahas, tanpa menjanjikan sesuatu yang tidak ada di dalam tulisan. Simpan penjelasan tambahan pada ringkasan agar judul tetap mudah dipindai.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/dc9f167d-b921-4155-b784-f22f3b836627.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nWrite several headline options and compare them with the article. Choose the version that remains accurate without the image for context. Also check the article card so long titles do not crowd the date and summary.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nBuat beberapa alternatif judul, lalu bandingkan dengan isi artikel. Pilih versi yang paling akurat ketika dibaca tanpa konteks gambar. Periksa juga tampilannya pada kartu artikel agar judul panjang tidak bertabrakan dengan tanggal dan ringkasan.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "A headline should explain what the reader will find. Use specific words and make sure the article delivers on its promise.", "idn": "Judul perlu menjelaskan apa yang akan dibaca. Gunakan kata yang spesifik dan pastikan isi artikel memenuhi janji pada judul."}}', 'https://cdn.dicobainaja.com/uploads/dc9f167d-b921-4155-b784-f22f3b836627.png', 'menulis-judul-artikel-yang-jelas-1791359671', 'active', '2026-10-07 14:54:31.37+07', NULL, '2026-10-07 15:17:39.027+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (9, 'cc1f1c38-549c-45e9-a1bc-f3f78df26fe0', 1, '{"title": {"eng": "Build an About Us Page", "idn": "Menyusun Halaman Tentang Kami"}, "content": [{"cta": null, "text": {"eng": "Explain who your team is, what you do, and how people can reach you. A short, concrete story is easier to understand.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nPeople visiting an About Us page want to understand who is behind the service. Describe your work through concrete examples and avoid claims that are difficult to support. A short explanation of your process can help set reasonable expectations.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Jelaskan siapa tim kamu, pekerjaan yang dilakukan, dan cara menghubungi kalian. Cerita singkat yang konkret lebih mudah dipahami.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nPembaca halaman Tentang Kami ingin memahami siapa yang ada di balik layanan. Ceritakan pekerjaan yang dilakukan dengan contoh konkret dan hindari klaim yang sulit dibuktikan. Informasi singkat tentang proses kerja dapat membantu membentuk ekspektasi yang wajar.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/0d1d5184-08ed-4753-85cd-3100191216c3.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nStart with the team’s identity, followed by its main services and contact details. Make sure photos and contact information reflect the current situation. Ask team members to review the text so the description matches the customer experience.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nSusun cerita mulai dari identitas tim, layanan utama, lalu cara menghubungi kalian. Pastikan foto dan informasi kontak masih sesuai keadaan sekarang. Minta anggota tim membaca ulang agar deskripsi perusahaan tidak berbeda dengan pengalaman pelanggan.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Explain who your team is, what you do, and how people can reach you. A short, concrete story is easier to understand.", "idn": "Jelaskan siapa tim kamu, pekerjaan yang dilakukan, dan cara menghubungi kalian. Cerita singkat yang konkret lebih mudah dipahami."}}', 'https://cdn.dicobainaja.com/uploads/0d1d5184-08ed-4753-85cd-3100191216c3.png', 'menyusun-halaman-tentang-kami-1791359671', 'active', '2026-10-07 14:54:31.38+07', NULL, '2026-10-07 15:17:39.028+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (11, '37b71d0c-e945-4aec-a4ed-03a45347168a', 1, '{"title": {"eng": "Plan a Simple Content Calendar", "idn": "Merencanakan Kalender Konten Sederhana"}, "content": [{"cta": null, "text": {"eng": "Record topics, owners, and target publishing dates. Start with a realistic schedule to keep writing consistent.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nA content calendar does not need to be complicated to be useful. Start with topics that answer reader questions and assign an owner to each article. Leave time for editing and checking images before publication.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Catat topik, penanggung jawab, dan tanggal target publikasi. Mulai dari jadwal yang realistis agar proses menulis tetap konsisten.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nKalender konten tidak perlu rumit untuk berguna. Mulailah dengan daftar topik yang menjawab pertanyaan pembaca dan tentukan siapa yang menyiapkan setiap artikel. Sisakan waktu untuk penyuntingan dan pemeriksaan gambar sebelum tanggal terbit.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/f374d17c-a037-413c-8af7-59d48819a251.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nReview the schedule regularly with the people producing the content. If a topic needs more research, adjust the date instead of rushing an unfinished article. Track its progress so the team can see where help is needed.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nTinjau jadwal secara berkala bersama orang yang mengerjakan konten. Jika suatu topik membutuhkan riset tambahan, pindahkan tanggalnya daripada memaksakan tulisan yang belum siap. Catat status pekerjaan agar tim mengetahui bagian yang masih membutuhkan bantuan.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Record topics, owners, and target publishing dates. Start with a realistic schedule to keep writing consistent.", "idn": "Catat topik, penanggung jawab, dan tanggal target publikasi. Mulai dari jadwal yang realistis agar proses menulis tetap konsisten."}}', 'https://cdn.dicobainaja.com/uploads/f374d17c-a037-413c-8af7-59d48819a251.png', 'merencanakan-kalender-konten-sederhana-1791359671', 'active', '2026-10-07 14:54:31.389+07', NULL, '2026-10-07 15:17:39.029+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (14, '4c6f0742-84d7-47a2-902f-3b4ac77c7a47', 1, '{"title": {"eng": "Review Your Website on Mobile", "idn": "Memeriksa Tampilan Website di Ponsel"}, "content": [{"cta": null, "text": {"eng": "Try opening menus, reading articles, and filling in forms on a small screen. Look for cramped text and buttons that are hard to tap.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nSmall screens can significantly change the reading experience. A compact desktop headline may take several lines on a phone. Watch text width, button spacing, and images that shift the page as they load.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Coba buka menu, baca artikel, dan isi formulir melalui layar kecil. Perhatikan teks yang terlalu rapat serta tombol yang sulit disentuh.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nLayar kecil dapat mengubah pengalaman membaca secara signifikan. Judul yang terlihat ringkas pada desktop mungkin memerlukan banyak baris di ponsel. Perhatikan lebar teks, jarak tombol, serta gambar yang membuat halaman bergeser saat dimuat.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/5f6a5e10-ea75-4eb7-a4d7-ce345c48897c.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nTry pages in portrait and landscape with enlarged text. Make sure forms remain usable when the keyboard appears. Record issues around user tasks so improvements go beyond appearance alone.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nCoba halaman pada posisi tegak dan mendatar dengan ukuran teks yang diperbesar. Pastikan formulir tetap dapat diisi ketika keyboard muncul. Catat masalah berdasarkan tugas pengguna agar perbaikan tidak berhenti pada penampilan visual saja.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Try opening menus, reading articles, and filling in forms on a small screen. Look for cramped text and buttons that are hard to tap.", "idn": "Coba buka menu, baca artikel, dan isi formulir melalui layar kecil. Perhatikan teks yang terlalu rapat serta tombol yang sulit disentuh."}}', 'https://cdn.dicobainaja.com/uploads/5f6a5e10-ea75-4eb7-a4d7-ce345c48897c.png', 'memeriksa-tampilan-website-di-ponsel-1791359671', 'active', '2026-10-07 14:54:31.406+07', NULL, '2026-10-07 15:17:39.031+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (16, '8a084097-11d1-4713-80ce-db418db2abfd', 1, '{"title": {"eng": "Prepare Content Before Launch", "idn": "Menyiapkan Konten Sebelum Peluncuran"}, "content": [{"cta": null, "text": {"eng": "Check headings, images, links, and contact information before publishing. Use a short checklist to avoid missing important details.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nA polished launch starts with complete content. Make sure no placeholder text remains and every image has a clear purpose. Test contact information and main links directly instead of only reviewing the design.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Periksa judul, gambar, tautan, dan informasi kontak sebelum halaman dipublikasikan. Gunakan daftar pemeriksaan singkat agar tidak ada bagian yang terlewat.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nPeluncuran yang rapi dimulai dari konten yang lengkap. Pastikan tidak ada teks contoh yang tertinggal dan setiap gambar memiliki tujuan yang jelas. Informasi kontak serta tautan utama perlu diperiksa langsung, bukan hanya dilihat pada rancangan.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/1b55246a-36b6-4069-9069-eed1103abd73.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nReview the site as a first-time visitor. Open pages through direct links, explore menus, and try the forms. Record findings with page addresses and reproduction steps so they are easy to understand and fix.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nLakukan pemeriksaan sebagai pengunjung yang baru pertama datang. Buka halaman melalui tautan langsung, telusuri menu, dan coba formulir. Catat temuan dengan alamat halaman dan langkah reproduksi agar orang yang memperbaiki mudah memahaminya.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Check headings, images, links, and contact information before publishing. Use a short checklist to avoid missing important details.", "idn": "Periksa judul, gambar, tautan, dan informasi kontak sebelum halaman dipublikasikan. Gunakan daftar pemeriksaan singkat agar tidak ada bagian yang terlewat."}}', 'https://cdn.dicobainaja.com/uploads/1b55246a-36b6-4069-9069-eed1103abd73.png', 'menyiapkan-konten-sebelum-peluncuran-1791359671', 'active', '2026-10-07 14:54:31.419+07', NULL, '2026-10-07 15:17:39.032+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (18, '7be6e0e5-c876-449f-aef0-75b902d7bcc9', 1, '{"title": {"eng": "Maintain Your Published Content", "idn": "Merawat Konten yang Sudah Dipublikasikan"}, "content": [{"cta": null, "text": {"eng": "Review older articles periodically for broken links and outdated information. Record changes to make future updates easier.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nPublished content still needs attention. Product information, ordering processes, and contact details can change over time. Prioritize frequently visited pages and information that matters to reader decisions.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Tinjau artikel lama secara berkala untuk menemukan tautan rusak dan informasi yang tidak sesuai lagi. Catat perubahan agar pembaruan berikutnya lebih mudah.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nKonten yang sudah terbit tetap membutuhkan perhatian. Informasi produk, proses pemesanan, dan alamat kontak dapat berubah seiring waktu. Prioritaskan halaman yang sering dikunjungi atau berisi informasi yang penting bagi keputusan pembaca.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/6a2ddb0f-7c0e-414d-bb03-841f0648cfc5.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nList articles that need review and explain why they need updating. Separate factual, link, and language changes to make the work easier to assign. After updating, check the public page to confirm the changes appear as intended.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nBuat daftar artikel yang perlu ditinjau beserta alasan pembaruannya. Pisahkan perbaikan fakta, tautan, dan tata bahasa agar pekerjaan mudah dibagi. Sesudah memperbarui, periksa kembali halaman publik untuk memastikan perubahan tampil sesuai harapan.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Review older articles periodically for broken links and outdated information. Record changes to make future updates easier.", "idn": "Tinjau artikel lama secara berkala untuk menemukan tautan rusak dan informasi yang tidak sesuai lagi. Catat perubahan agar pembaruan berikutnya lebih mudah."}}', 'https://cdn.dicobainaja.com/uploads/6a2ddb0f-7c0e-414d-bb03-841f0648cfc5.png', 'merawat-konten-yang-sudah-dipublikasikan-1791359671', 'active', '2026-10-07 14:54:31.43+07', NULL, '2026-10-07 15:17:39.033+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (12, '000dfd7b-1bc4-419e-9571-7340eb032fd7', 1, '{"title": {"eng": "Organize FAQs Around Reader Questions", "idn": "Menata FAQ Berdasarkan Pertanyaan Pembaca"}, "content": [{"cta": null, "text": {"eng": "Collect recurring questions before writing your FAQ. Answer directly and place the most important questions first.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nGood questions come from real conversations with readers. Group similar questions and choose wording people will recognize. Answers should address the main issue before adding conditions or exceptions.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Kumpulkan pertanyaan yang sering muncul sebelum menulis FAQ. Jawab dengan kalimat langsung dan letakkan pertanyaan terpenting di awal.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nPertanyaan yang baik berasal dari percakapan nyata dengan pembaca. Kelompokkan pertanyaan yang mirip dan pilih kalimat yang paling mudah dikenali. Jawaban sebaiknya langsung menjelaskan inti masalah sebelum memberikan syarat atau pengecualian.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/71204d5a-c962-42db-be6a-06df227981a2.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nReview FAQs whenever products or service processes change. Outdated answers can lead readers to take the wrong steps. If an explanation is long, provide a summary and link to a dedicated page for the details.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nPeriksa FAQ ketika produk atau proses layanan berubah. Jawaban lama yang tidak diperbarui dapat membuat pembaca mengambil langkah yang salah. Jika penjelasannya panjang, berikan ringkasan dan arahkan ke halaman khusus yang membahas detailnya.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Collect recurring questions before writing your FAQ. Answer directly and place the most important questions first.", "idn": "Kumpulkan pertanyaan yang sering muncul sebelum menulis FAQ. Jawab dengan kalimat langsung dan letakkan pertanyaan terpenting di awal."}}', 'https://cdn.dicobainaja.com/uploads/71204d5a-c962-42db-be6a-06df227981a2.png', 'menata-faq-berdasarkan-pertanyaan-pembaca-1791359671', 'active', '2026-10-07 14:54:31.397+07', NULL, '2026-10-07 15:17:39.029+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (13, 'c9ea54ab-371c-43d0-a7e9-6c574a7d46e7', 1, '{"title": {"eng": "Write Informative Product Descriptions", "idn": "Menulis Deskripsi Produk yang Informatif"}, "content": [{"cta": null, "text": {"eng": "Explain the product purpose, dimensions, materials, and usage limits. Relevant details help readers decide whether it suits them.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nSeparate usage benefits from product specifications. Benefits explain the needs a product can address, while specifications help people compare options. Avoid generic wording that says little about what the product can do.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Terangkan fungsi produk, ukuran, bahan, dan batas penggunaannya. Detail yang relevan membantu pembaca menentukan apakah produk cocok untuk mereka.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nPisahkan manfaat penggunaan dari spesifikasi produk. Manfaat menjelaskan kebutuhan yang dapat dibantu, sedangkan spesifikasi memberi informasi untuk membandingkan pilihan. Hindari kata-kata umum yang tidak memberi petunjuk tentang kemampuan produk.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/272528a8-953f-43e5-87c3-bd22c8d703fe.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nCheck whether dimensions, materials, package contents, and usage conditions are clear. Use consistent units across products. Ask someone unfamiliar with the product to read the description and identify missing information.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nPeriksa apakah ukuran, bahan, isi paket, dan ketentuan penggunaan sudah jelas. Gunakan satuan yang konsisten pada semua produk. Mintalah seseorang yang belum mengenal produk membaca deskripsi dan menyebutkan informasi yang masih kurang.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Explain the product purpose, dimensions, materials, and usage limits. Relevant details help readers decide whether it suits them.", "idn": "Terangkan fungsi produk, ukuran, bahan, dan batas penggunaannya. Detail yang relevan membantu pembaca menentukan apakah produk cocok untuk mereka."}}', 'https://cdn.dicobainaja.com/uploads/272528a8-953f-43e5-87c3-bd22c8d703fe.png', 'menulis-deskripsi-produk-yang-informatif-1791359671', 'active', '2026-10-07 14:54:31.402+07', NULL, '2026-10-07 15:17:39.03+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (15, '6ae6ef60-8a48-47e1-812b-e3cdb6a7fc23', 1, '{"title": {"eng": "Keep Website Language Consistent", "idn": "Menjaga Konsistensi Bahasa di Website"}, "content": [{"cta": null, "text": {"eng": "Keep a list of terms used in menus, buttons, and system messages. Consistent wording helps visitors understand each page.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nSmall terminology differences can create uncertainty. If one page uses Save, avoid a different label for the same action without a reason. A short writing guide helps new team members follow existing conventions.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Buat daftar istilah yang digunakan pada menu, tombol, dan pesan sistem. Pilihan kata yang konsisten membantu pengunjung memahami setiap halaman.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nPerbedaan istilah kecil dapat menimbulkan keraguan. Jika satu halaman memakai kata Simpan, jangan gunakan istilah berbeda untuk tindakan yang sama tanpa alasan. Aturan penulisan singkat membantu tim baru mengikuti pola yang sudah digunakan.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/1f62608c-dd7c-465a-acd6-58f2b066027f.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nReview menus, buttons, forms, and error messages together. For bilingual content, compare meaning rather than sentence length. Use natural wording in each language while preserving the same intent.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nPeriksa menu, tombol, formulir, dan pesan kesalahan dalam satu sesi. Untuk konten bilingual, bandingkan makna kedua versi, bukan hanya panjang kalimatnya. Gunakan istilah yang alami dalam setiap bahasa sambil mempertahankan maksud yang sama.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Keep a list of terms used in menus, buttons, and system messages. Consistent wording helps visitors understand each page.", "idn": "Buat daftar istilah yang digunakan pada menu, tombol, dan pesan sistem. Pilihan kata yang konsisten membantu pengunjung memahami setiap halaman."}}', 'https://cdn.dicobainaja.com/uploads/1f62608c-dd7c-465a-acd6-58f2b066027f.png', 'menjaga-konsistensi-bahasa-di-website-1791359671', 'active', '2026-10-07 14:54:31.413+07', NULL, '2026-10-07 15:17:39.032+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (17, '6ab87468-dc65-4d1d-8713-759883284e86', 1, '{"title": {"eng": "Organize Articles for Easier Discovery", "idn": "Mengelompokkan Artikel agar Mudah Dicari"}, "content": [{"cta": null, "text": {"eng": "Use clear themes to help readers explore your article collection. Make summaries explain the content without repeating the entire headline.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nUseful grouping follows reader needs. Overly broad topics do little to help discovery, while too many small groups create clutter. Start with a few themes that genuinely represent the article collection.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Gunakan tema yang jelas untuk membantu pembaca menjelajahi koleksi artikel. Pastikan ringkasan menjelaskan isi tanpa mengulang seluruh judul.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nPengelompokan yang berguna mengikuti kebutuhan pembaca. Topik yang terlalu luas sulit membantu pencarian, sedangkan terlalu banyak kelompok kecil membuat pilihan terasa ramai. Mulailah dari beberapa tema yang benar-benar mewakili koleksi artikel.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/dc9f167d-b921-4155-b784-f22f3b836627.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nReview headlines and summaries together on the listing page. Readers should be able to distinguish two articles without opening both. Also test pagination and return links to keep browsing comfortable.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nPeriksa judul dan ringkasan pada halaman daftar sebagai satu kesatuan. Pembaca perlu dapat membedakan dua artikel tanpa membuka keduanya. Uji juga perpindahan halaman dan tombol kembali agar penjelajahan koleksi tetap nyaman.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Use clear themes to help readers explore your article collection. Make summaries explain the content without repeating the entire headline.", "idn": "Gunakan tema yang jelas untuk membantu pembaca menjelajahi koleksi artikel. Pastikan ringkasan menjelaskan isi tanpa mengulang seluruh judul."}}', 'https://cdn.dicobainaja.com/uploads/dc9f167d-b921-4155-b784-f22f3b836627.png', 'mengelompokkan-artikel-agar-mudah-dicari-1791359671', 'active', '2026-10-07 14:54:31.425+07', NULL, '2026-10-07 15:17:39.033+07');
INSERT INTO public.blog (id, public_id, "userId", content_payload, cover_image, slug, status, created_at, deleted_at, updated_at) OVERRIDING SYSTEM VALUE VALUES (19, '64d5f90a-ea0d-4197-8dde-b5718b40b936', 1, '{"title": {"eng": "Write Relevant Calls to Action", "idn": "Menyusun Ajakan Bertindak yang Relevan"}, "content": [{"cta": null, "text": {"eng": "Match buttons to the context of the page. Describe the next action briefly, such as viewing products or contacting the team.\n\nStart with one frequently visited page. Note the unclear parts before making changes.\n\nA call to action should explain where a button leads. Specific labels give clearer guidance than vague instructions. Place the button after information that helps readers decide whether they want to continue.\n\nTo put this into practice, use an example from the page you are working on. Write down what already helps readers and which parts still raise questions. These brief notes can guide discussion before the team changes the design or adds new features.", "idn": "Sesuaikan tombol dengan konteks halaman. Jelaskan tindakan berikutnya secara singkat, misalnya melihat produk atau menghubungi tim.\n\nMulai dari satu halaman yang paling sering dikunjungi. Catat bagian yang belum jelas sebelum melakukan perubahan.\n\nAjakan bertindak sebaiknya menjelaskan tujuan setelah tombol ditekan. Label yang spesifik memberi petunjuk lebih jelas daripada perintah yang terlalu umum. Letakkan tombol setelah informasi yang membantu pembaca memutuskan apakah ingin melanjutkan.\n\nUntuk menerapkannya, gunakan contoh dari halaman yang sedang kamu kerjakan. Tuliskan apa yang sudah membantu pembaca dan bagian mana yang masih menimbulkan pertanyaan. Catatan singkat ini dapat menjadi dasar diskusi sebelum tim mengubah desain atau menambahkan fitur baru."}, "image": "https://cdn.dicobainaja.com/uploads/0d1d5184-08ed-4753-85cd-3100191216c3.png"}, {"cta": {"url": "/product", "label": {"eng": "View products", "idn": "Lihat produk"}}, "text": {"eng": "Next steps\n\nMake one small improvement, then check the result on desktop and mobile. Ask someone else to try the page and note any confusing parts.\n\nUse those observations to decide what to change next.\n\nCheck that the button label matches its destination. If it offers a product list, make sure visitors arrive at a relevant listing. Test the link on mobile and desktop and make sure returning to the article is straightforward.\n\nOnce the changes are ready, ask someone to try the page without instructions. Listen for places where they pause or ask questions. Fix the clearest issue first, then repeat the review to make sure the solution actually helps.", "idn": "Langkah berikutnya\n\nBuat satu perbaikan kecil, lalu periksa hasilnya pada desktop dan ponsel. Mintalah orang lain mencoba halaman tersebut dan mencatat bagian yang membingungkan.\n\nGunakan temuan itu untuk menentukan perubahan berikutnya.\n\nPeriksa kesesuaian antara label tombol dan halaman tujuan. Jika tombol menawarkan daftar produk, pastikan pengunjung tiba pada daftar yang relevan. Coba tautan dari ponsel dan desktop, lalu pastikan pengguna dapat kembali ke artikel dengan mudah.\n\nSetelah perubahan selesai, mintalah satu orang mencoba halaman tanpa diberi petunjuk. Dengarkan bagian yang membuatnya berhenti atau bertanya. Perbaiki masalah paling jelas terlebih dahulu, lalu ulangi pemeriksaan untuk memastikan solusi tersebut benar-benar membantu."}, "image": ""}], "excerpt": {"eng": "Match buttons to the context of the page. Describe the next action briefly, such as viewing products or contacting the team.", "idn": "Sesuaikan tombol dengan konteks halaman. Jelaskan tindakan berikutnya secara singkat, misalnya melihat produk atau menghubungi tim."}}', 'https://cdn.dicobainaja.com/uploads/8e6f0be2-7964-4a3e-b80f-3a092a2fea2f.png', 'menyusun-ajakan-bertindak-yang-relevan-1791359671', 'active', '2026-10-07 14:54:31.437+07', NULL, '2026-10-07 16:05:06.86+07');


